class Solution {
public:
    bool threeFibonacciSum(int n) {
        if (n % 2 != 0) return false;
        long long x = n / 2LL;
        return isFibonacci(x);
    }
private:
    bool isPerfectSquare(long long v) {
        long long r = (long long)sqrt((long double)v);
        while (r * r < v) ++r;
        while (r * r > v) --r;
        return r * r == v;
    }
    bool isFibonacci(long long x) {
        long long d1 = 5LL * x * x + 4;
        long long d2 = 5LL * x * x - 4;
        return isPerfectSquare(d1) || isPerfectSquare(d2);
    }
};

