class Solution {
    public boolean threeFibonacciSum(int n) {
        if (n % 2 != 0) return false;
        long x = n / 2L;
        return isFibonacci(x);
    }

    private boolean isPerfectSquare(long v) {
        long r = (long) Math.sqrt((double) v);
        while (r * r < v) ++r;
        while (r * r > v) --r;
        return r * r == v;
    }

    private boolean isFibonacci(long x) {
        long d1 = 5L * x * x + 4;
        long d2 = 5L * x * x - 4;
        return isPerfectSquare(d1) || isPerfectSquare(d2);
    }
}

