/**
 * @param {number} n
 * @return {boolean}
 */
var threeFibonacciSum = function(n) {
    if (n % 2 !== 0) return false;
    const x = BigInt(n) / 2n;
    return isFibonacci(x);
};

function isPerfectSquare(v) {
    if (v < 0n) return false;
    let low = 0n;
    let high = v;
    while (low <= high) {
        const mid = (low + high) >> 1n;
        const sq = mid * mid;
        if (sq === v) return true;
        if (sq < v) {
            low = mid + 1n;
        } else {
            high = mid - 1n;
        }
    }
    return false;
}

function isFibonacci(x) {
    const d1 = 5n * x * x + 4n;
    const d2 = 5n * x * x - 4n;
    return isPerfectSquare(d1) || isPerfectSquare(d2);
}
